CREATE TABLE streak_def (id uuid PRIMARY KEY,"userId" uuid NOT NULL REFERENCES app_user(id),title text NOT NULL CHECK(length(trim(title))>0),scope text NOT NULL CHECK(scope IN ('goal','skill','profile','global')),"scopeId" uuid,"startDate" date NOT NULL,status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','archived')),"createdAt" timestamptz(3) NOT NULL DEFAULT now(),"updatedAt" timestamptz(3) NOT NULL DEFAULT now(),UNIQUE(id,"userId"),CHECK((scope='global')=("scopeId" IS NULL)));
CREATE INDEX streak_owner_status ON streak_def("userId",status,"createdAt");
CREATE TABLE streak_rule_version (id uuid PRIMARY KEY,"userId" uuid NOT NULL REFERENCES app_user(id),"streakId" uuid NOT NULL,version integer NOT NULL CHECK(version>0),"effectiveFrom" date NOT NULL,rules jsonb NOT NULL CHECK(jsonb_typeof(rules)='object'),"createdAt" timestamptz(3) NOT NULL DEFAULT now(),UNIQUE(id,"userId"),UNIQUE("streakId",version),UNIQUE("streakId","effectiveFrom"),FOREIGN KEY("streakId","userId") REFERENCES streak_def(id,"userId"));
CREATE TABLE streak_record (id uuid PRIMARY KEY,"userId" uuid NOT NULL REFERENCES app_user(id),"streakId" uuid NOT NULL,"ruleVersionId" uuid NOT NULL,"periodStart" date NOT NULL,"periodEnd" date NOT NULL,result text NOT NULL CHECK(result IN ('met','missed','rest','paused','grace')),value double precision NOT NULL CHECK(value>=0 AND value<='1e100'::double precision),provisional boolean NOT NULL DEFAULT false,reason text NOT NULL,"sourceHash" text NOT NULL,"correctsRecordId" uuid,"beforeReason" text,"createdAt" timestamptz(3) NOT NULL DEFAULT now(),UNIQUE(id,"userId"),FOREIGN KEY("streakId","userId") REFERENCES streak_def(id,"userId"),FOREIGN KEY("ruleVersionId","userId") REFERENCES streak_rule_version(id,"userId"),FOREIGN KEY("correctsRecordId","userId") REFERENCES streak_record(id,"userId"),CHECK("periodEnd">="periodStart"),CHECK(("correctsRecordId" IS NULL)=("beforeReason" IS NULL)));
CREATE INDEX streak_record_calendar ON streak_record("userId","streakId","periodStart","createdAt");
CREATE TRIGGER streak_rule_immutable BEFORE UPDATE OR DELETE ON streak_rule_version FOR EACH ROW EXECUTE FUNCTION protect_append_only_history();
CREATE TRIGGER streak_record_immutable BEFORE UPDATE OR DELETE ON streak_record FOR EACH ROW EXECUTE FUNCTION protect_append_only_history();
CREATE FUNCTION check_streak_ownership() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
  IF TG_TABLE_NAME='streak_def' THEN
    IF TG_OP='UPDATE' AND (NEW."userId",NEW.scope,NEW."scopeId",NEW."startDate") IS DISTINCT FROM (OLD."userId",OLD.scope,OLD."scopeId",OLD."startDate") THEN RAISE EXCEPTION 'Streak ownership, scope and start date are immutable'; END IF;
    IF (NEW.scope='goal' AND NOT EXISTS(SELECT 1 FROM goal WHERE id=NEW."scopeId" AND "userId"=NEW."userId")) OR (NEW.scope='skill' AND NOT EXISTS(SELECT 1 FROM skill WHERE id=NEW."scopeId" AND "userId"=NEW."userId")) OR (NEW.scope='profile' AND NOT EXISTS(SELECT 1 FROM profile WHERE id=NEW."scopeId" AND "userId"=NEW."userId")) THEN RAISE EXCEPTION 'Streak scope must belong to owner'; END IF;
  ELSE
    IF NOT EXISTS(SELECT 1 FROM streak_rule_version WHERE id=NEW."ruleVersionId" AND "streakId"=NEW."streakId" AND "userId"=NEW."userId") THEN RAISE EXCEPTION 'Evaluation rule belongs to another streak'; END IF;
    IF NEW."correctsRecordId" IS NOT NULL AND NOT EXISTS(SELECT 1 FROM streak_record WHERE id=NEW."correctsRecordId" AND "streakId"=NEW."streakId" AND "periodStart"=NEW."periodStart" AND "userId"=NEW."userId") THEN RAISE EXCEPTION 'Correction must reference the same streak period'; END IF;
  END IF; RETURN NEW;
END $$;
CREATE TRIGGER streak_scope_owner BEFORE INSERT OR UPDATE ON streak_def FOR EACH ROW EXECUTE FUNCTION check_streak_ownership();
CREATE TRIGGER streak_record_owner BEFORE INSERT ON streak_record FOR EACH ROW EXECUTE FUNCTION check_streak_ownership();
CREATE TABLE user_channel (id uuid PRIMARY KEY,"userId" uuid NOT NULL REFERENCES app_user(id),channel text NOT NULL CHECK(channel IN ('ntfy','telegram')),"encryptedConfig" text NOT NULL,"verifiedAt" timestamptz(3),enabled boolean NOT NULL DEFAULT false,privacy boolean NOT NULL DEFAULT true,"linkCodeHash" text,"linkExpiresAt" timestamptz(3),"pollOffset" bigint NOT NULL DEFAULT 0,"createdAt" timestamptz(3) NOT NULL DEFAULT now(),"updatedAt" timestamptz(3) NOT NULL DEFAULT now(),UNIQUE(id,"userId"),UNIQUE("userId",channel));
CREATE TABLE notification_route (id uuid PRIMARY KEY,"userId" uuid NOT NULL REFERENCES app_user(id),"profileId" uuid,type text NOT NULL,"routeKey" text NOT NULL,channels text[] NOT NULL,topic text,"createdAt" timestamptz(3) NOT NULL DEFAULT now(),"updatedAt" timestamptz(3) NOT NULL DEFAULT now(),UNIQUE("userId","routeKey"),FOREIGN KEY("profileId","userId") REFERENCES profile(id,"userId"),CHECK(channels <@ ARRAY['ntfy','telegram']::text[]),CHECK(topic IS NULL OR topic ~ '^[a-zA-Z0-9_-]{16,128}$'));
CREATE TABLE telegram_update (id uuid PRIMARY KEY,"userId" uuid NOT NULL REFERENCES app_user(id),"channelId" uuid NOT NULL,"updateId" bigint NOT NULL,"botHash" text NOT NULL,outcome text NOT NULL,"createdAt" timestamptz(3) NOT NULL DEFAULT now(),UNIQUE("channelId","botHash","updateId"),FOREIGN KEY("channelId","userId") REFERENCES user_channel(id,"userId"));
CREATE TRIGGER telegram_update_immutable BEFORE UPDATE OR DELETE ON telegram_update FOR EACH ROW EXECUTE FUNCTION protect_append_only_history();
CREATE TABLE notification_snooze (id uuid PRIMARY KEY,"userId" uuid NOT NULL REFERENCES app_user(id),"taskId" uuid NOT NULL,until timestamptz(3) NOT NULL,"createdAt" timestamptz(3) NOT NULL DEFAULT now(),"updatedAt" timestamptz(3) NOT NULL DEFAULT now(),UNIQUE("userId","taskId"),FOREIGN KEY("taskId","userId") REFERENCES task(id,"userId"));
ALTER TABLE reminder_rule DROP CONSTRAINT reminder_policy;
ALTER TABLE reminder_rule ADD CONSTRAINT reminder_policy CHECK("repeatPolicy" IN ('once','until_completed') AND channel IN ('ntfy','telegram'));
ALTER TABLE notification ADD CONSTRAINT notification_channel CHECK(channel IN ('ntfy','telegram'));
